<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Struk {{ $o->order_code }} — KriukKita</title><link rel="stylesheet" href="{{ asset('assets/css/kriuk.css') }}"><style>body{background:#f8f5ef}.print-tools{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;padding:25px 10px}.paper{max-width:440px;margin:0 auto 45px;background:#fff;border:1px dashed #d6c3aa;padding:33px;border-radius:8px;box-shadow:0 12px 35px #0001}.paper h1{text-align:center;font-size:28px;margin:5px 0;color:#242019}.paper .cent{text-align:center}.paper hr{border:0;border-top:1px dashed #c7b8a9;margin:19px 0}.line{display:flex;justify-content:space-between;gap:12px;margin:9px 0;font-size:13px}.line span:last-child{text-align:right}.small{color:#6c6258;font-size:12px}.total{font-weight:900;font-size:18px}.tool{padding:11px 16px;border:1px solid #e0d0be;border-radius:9px;background:white;cursor:pointer;font-weight:800;color:#242019;text-decoration:none}.tool.primary{background:#f36b32;border-color:#f36b32;color:white}@media print{.print-tools{display:none}.paper{box-shadow:none;border:0;padding:4px;max-width:80mm;margin:0 auto}body{background:white}@page{size:auto;margin:8mm}}</style></head><body>
