<article class="paper" id="receipt"><div class="cent"><h1>Kriuk<span style="color:#f36b32">Kita.</span></h1><p class="small">Keripik Lokal • Rasa Juara</p><p class="small">BUKTI PEMBAYARAN</p></div><hr><div class="line"><span>Nomor Struk</span><strong>{{ $o->order_code }}</strong></div><div class="line"><span>Tanggal</span><span>{{ \Carbon\Carbon::parse($o->paid_at)->format('d/m/Y H:i') }}</span></div><div class="line"><span>Kasir / Kanal</span><span>{{ $o->channel === 'kasir' ? 'Kasir Tunai' : 'Pembelian Online' }}</span></div><div class="line"><span>Nama</span><span>{{ $o->buyer_name }}</span></div><hr>
