<script>
const receipt={code:@json($o->order_code),total:@json($o->total_amount),paid:@json($o->cash_received),change:@json($o->cash_change),channel:@json($o->channel),buyer:@json($o->buyer_name),method:@json($o->payment_method),date:@json($o->paid_at),items:@json($receiptItems)};
const money=n=>'Rp'+Math.round(Number(n)||0).toLocaleString('id-ID');
const link=location.href;
document.getElementById('copy-link').onclick=()=>navigator.clipboard.writeText(link).then(()=>alert('Link struk disalin.')).catch(()=>prompt('Salin link struk',link));
document.getElementById('share-wa').onclick=()=>{const lines=[`*STRUK KRIUKKITA*`,receipt.code,`Pelanggan: ${receipt.buyer}`,...receipt.items.map(x=>`${x.name} (${x.weight}) × ${x.qty} = ${money(x.price*x.qty)}`),`*Total: ${money(receipt.total)}*`,`Metode: ${receipt.method}`,`Struk: ${link}`];window.open('https://wa.me/?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener')};
document.getElementById('save-image').onclick=()=>{const items=receipt.items;const width=700,height=Math.max(680,440+items.length*62);const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.fillStyle='#242019';ctx.textAlign='center';ctx.font='bold 40px Arial';ctx.fillText('KriukKita.',width/2,64);ctx.font='19px Arial';ctx.fillText('Bukti Pembayaran',width/2,105);ctx.textAlign='left';ctx.font='19px Arial';const line=(k,v,y)=>{ctx.fillText(k,45,y);ctx.textAlign='right';ctx.fillText(v,width-45,y);ctx.textAlign='left'};line('No. Struk',receipt.code,158);line('Pembeli',receipt.buyer.slice(0,24),195);line('Metode',receipt.method,232);let y=290;ctx.fillRect(45,y,610,1);y+=40;items.forEach(x=>{ctx.font='bold 18px Arial';ctx.fillText(x.name.slice(0,34),45,y);ctx.font='17px Arial';line(`${x.weight} x ${x.qty}`,money(x.price*x.qty),y+26);y+=62});ctx.fillRect(45,y,610,1);y+=40;ctx.font='bold 25px Arial';line('TOTAL',money(receipt.total),y);if(receipt.channel==='kasir'){y+=40;ctx.font='18px Arial';line('Diterima',money(receipt.paid),y);y+=30;line('Kembalian',money(receipt.change),y)}ctx.textAlign='center';ctx.font='18px Arial';ctx.fillText('Terima kasih sudah berbelanja!',350,Math.min(height-35,y+75));const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='struk-'+receipt.code+'.png';a.click()};
</script></body></html>
